(7145343, 1095609, 114225, '<td valign="top">Hmm, I can see what you were going for. But the lighting makes this difficult. It took me no less than 15 seconds of starting at this to see that the bulbs are laying on their side.</td>', 'Hmm, I can see what you were going for. But the lighting makes this difficult. It took me no less than 15 seconds of starting at this to see that the bulbs are laying on their side.', '2013-12-20 16:34:22.000000', NULL, 1),
(7145344, 1095648, 114225, '<td valign="top">I bit more light, and this could be really cool. Try a strong light from the bottom to make it pop.</td>', 'I bit more light, and this could be really cool. Try a strong light from the bottom to make it pop.', '2013-12-20 16:34:49.000000', NULL, 1),
(7145345, 1095647, 114225, '<td valign="top">Great classic scene.</td>', 'Great classic scene.', '2013-12-20 16:35:00.000000', NULL, 1),
