(7145356, 1095592, 114225, '<td valign="top">That is an ornament I would love to own. A little better focus and less noise, and this would have scored higher from me.</td>', 'That is an ornament I would love to own. A little better focus and less noise, and this would have scored higher from me.', '2013-12-20 16:43:08.000000', NULL, 1),
(7145357, 1095597, 30712, '<td valign="top">A very formal image that is almost symmetrical but not quite - and it''s these differences that make it so special. It makes a grand statement.</td>', 'A very formal image that is almost symmetrical but not quite - and it''s these differences that make it so special. It makes a grand statement.', '2013-12-20 16:43:59.000000', NULL, 1),
