(7147679, 1095511, 14476, '<td valign="top">Ah, yes.  Big ornaments, big corporation (I bet).  Nice interpretation of both the challenge and the corporate art.</td>', 'Ah, yes.  Big ornaments, big corporation (I bet).  Nice interpretation of both the challenge and the corporate art.', '2013-12-26 16:29:17.000000', NULL, 1),
(7147680, 1095515, 14476, '<td valign="top">Now, this is pure fun.  Good one.</td>', 'Now, this is pure fun.  Good one.', '2013-12-26 16:29:44.000000', NULL, 1),
(7147681, 1095646, 14476, '<td valign="top">Fun collection.  I can see they look good under the tree.  (For photo purposes, it might be a good idea to straighten them a bit, so they aren''t marching down hill.)<br/>:)</td>', 'Fun collection.  I can see they look good under the tree.  (For photo purposes, it might be a good idea to straighten them a bit, so they aren''t marching down hill.):)', '2013-12-26 16:31:08.000000', NULL, 1),
(7147683, 1095436, 14476, '<td valign="top">I dunno why he''s "Bad."  He''s kinda cute there in his corner.</td>', 'I dunno why he''s "Bad."  He''s kinda cute there in his corner.', '2013-12-26 16:31:53.000000', NULL, 1),
(7147684, 1095655, 14476, '<td valign="top">Great shot of santa and his clone.</td>', 'Great shot of santa and his clone.', '2013-12-26 16:32:18.000000', NULL, 1),
