(7147686, 1095638, 109227, '<td valign="top">Beautiful, simple and my favorite.  Looks like RKT; if not, then take as a compliment.</td>', 'Beautiful, simple and my favorite.  Looks like RKT; if not, then take as a compliment.', '2013-12-26 16:34:03.000000', NULL, 1),
(7147687, 1095655, 109227, '<td valign="top">Beautifully done.  Love the Santa bokeh.</td>', 'Beautifully done.  Love the Santa bokeh.', '2013-12-26 16:34:45.000000', NULL, 1),
(7147688, 1095654, 14476, '<td valign="top">Nice little peek at santa in the store window.  The shadows/reflections give it a bit of mystery.  But the other surroundings just don''t do santa justice.  Still, it''s a fun bit of art.</td>', 'Nice little peek at santa in the store window.  The shadows/reflections give it a bit of mystery.  But the other surroundings just don''t do santa justice.  Still, it''s a fun bit of art.', '2013-12-26 16:35:18.000000', NULL, 1),
